    def neighbors(r, c):
        for dr, dc in ((-1,0),(1,0),(0,-1),(0,1)):
            nr, nc = r+dr, c+dc
            if 0 <= nr < rows and 0 <= nc < len(grid[nr]):
                yield nr, nc
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if (i, j) in visited:
                continue
            if grid[i][j] == 0:
                continue
            visited.add((i, j))
            for ni, nj in neighbors(i, j):
                if (ni, nj) not in visited and grid[ni][nj] != 0:
                    stack.append((ni, nj))
    count = 0
    for i in range(rows):
        for j in range(len(grid[i])):
            if grid[i][j] != 0 and (i, j) not in visited:
                dfs(i, j)
                count += 1
    return count

